struct VSOut {
    float4 pos : SV_POSITION;
    [[vk::location(0)]] float2 uv : TEXCOORD0;
};

VSOut VSMain(uint vid : SV_VertexID)
{
    VSOut o;
    o.uv = float2((vid << 1) & 2, vid & 2);
    o.pos = float4(o.uv * 2.0f - 1.0f, 0.0f, 1.0f);
    o.uv.y = 1.0f - o.uv.y;
    return o;
}

// Requires: texture image (add via Textures panel)
// Binds as combined image sampler: [[vk::combinedImageSampler]] [[vk::binding(0, 1)]]

cbuffer Host : register(b0)
{
    float time_sim_ms;
    float time_wall_ms;
    float delta_time_ms;
    uint  frame_index;
    float resolution_x;
    float resolution_y;
    float mouse_x;
    float mouse_y;
    uint  mouse_buttons;
    float scroll_delta_x;
    float scroll_delta_y;
    float drag_accum_x;
    float drag_accum_y;
    float scroll_accum_x;
    float scroll_accum_y;
    float pan_accum_x;
    float pan_accum_y;
};

[[vk::combinedImageSampler]] [[vk::binding(0, 1)]]
Texture2D tex0 : register(t0);
[[vk::combinedImageSampler]] [[vk::binding(0, 1)]]
SamplerState samp0 : register(s0);

struct VSOut {
    float4 pos : SV_POSITION;
    [[vk::location(0)]] float2 uv : TEXCOORD0;
};

float4 PSMain(VSOut i) : SV_Target
{
    float4 col = tex0.Sample(samp0, i.uv);
    return col;
}
